import pdfplumber
import re

pdf = pdfplumber.open(r'输出文件/Computer Systems A Programmers Perspective ( etc.)Plume_2015_English_— (z-library.sk, 1lib.sk, z-lib.sk).pdf')

# Find chapter starting pages by searching for chapter headings
chapters = {}
for i, page in enumerate(pdf.pages):
    text = page.extract_text()
    if text and re.search(r'^Chapter\s+\d+', text.strip()[:30]):
        ch_match = re.search(r'Chapter\s+(\d+)', text.strip()[:50])
        if ch_match:
            ch = int(ch_match.group(1))
            if ch not in chapters:
                chapters[ch] = i
                print(f'Chapter {ch}: page {i+1}')

print(f'\nTotal chapters found: {len(chapters)}')
pdf.close()
