{"content": "import pdfplumber

pdf = pdfplumber.open(r'输出文件/Computer Systems A Programmers Perspective ( etc.)Plume_2015_English_— (z-library.sk, 1lib.sk, z-lib.sk).pdf')

more_targets = [
    ("ASLR/NX/stack defense", ["address space layout", "nonexecutable", "stack randomization", "NX"]),
    ("Signal pitfalls", ["pending signal", "signal handler", "concurrent", "async-signal-safe"]),
    ("Strong vs weak symbol", ["strong symbol", "weak symbol", "multiple definition", "linker symbol"]),
    ("TLB magic", ["translation lookaside buffer", "TLB hit", "TLB miss"]),
    ("Nonlocal jump", ["nonlocal jump", "setjmp", "longjmp"]),
    ("Cache miss types", ["compulsory miss", "conflict miss", "capacity miss"]),
    ("Branch prediction", ["branch prediction", "mispredict"]),
    ("Loop unrolling rationale", ["loop unrolling", "unroll"]),
]

results = {}
for label, keywords in more_targets:
    results[label] = []

for i in range(80, min(2150, len(pdf.pages))):
    text = pdf.pages[i].extract_text()
    if not text:
        continue
    text_lower = text.lower()
    for label, keywords in more_targets:
        for kw in keywords:
            if kw.lower() in text_lower:
                paras = text.split('\n\n')
                for p in paras:
                    if kw.lower() in p.lower() and 80 < len(p) < 1000:
                        results[label].append((i+1, p.strip()[:700]))
                        break
                break

for label, matches in results.items():
    unique = {}
    for pg, para in matches:
        key = para[:100]
        if key not in unique:
            unique[key] = (pg, para)
    print(f'\n========== {label} ({len(unique)} unique) ==========')
    for pg, para in list(unique.values())[:3]:
        print(f'\n[PDF pg {pg}]')
        print(para[:600])
        print('---')

pdf.close()
", "path": "deep_extract2.py"}

