pdf = pdfplumber.open(r'输出文件/Computer Systems A Programmers Perspective ( etc.)Plume_2015_English_— (z-library.sk, 1lib.sk, z-lib.sk).pdf')

final_targets = [
    ("Three abstractions", "three fundamental abstractions"),
    ("Everything is file", "everything is a file"),
    ("Stack frame canary", "canary"),
    ("Cache thrashing fix", "thrashing"),
    ("Lazy binding PLT", "lazy binding"),
    ("Data-flow graph crit path", "critical path"),
    ("SIMD parallelism", "SIMD"),
]

results = {}
for label, kw in final_targets:
    results[label] = []

for i in range(80, min(2150, len(pdf.pages))):
    text = pdf.pages[i].extract_text()
    if not text:
        continue
    text_lower = text.lower()
    for label, kw in final_targets:
