{"content": "<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>CSAPP 系统知识图谱</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;600;700;900&family=JetBrains+Mono:wght@400;600&family=Noto+Serif+SC:wght@400;600;700;900&display=swap');

  :root {
    --bg: #0d1117;
    --bg-card: #161b22;
    --bg-elevated: #1c2333;
    --gold: #e6b800;
    --gold-dim: #8b7300;
    --accent: #58a6ff;
    --accent2: #3fb950;
    --text: #e6edf3;
    --text-dim: #8b949e;
    --text-muted: #6e7681;
    --border: #30363d;
    --radius: 12px;
    --shadow: 0 4px 24px rgba(0,0,0,0.4);
    --font-body: 'Inter', 'Noto Sans SC', sans-serif;
    --font-mono: 'JetBrains Mono', 'Fira Code', monospace;
    --font-display: 'Noto Serif SC', 'Georgia', serif;
  }

  * { margin: 0; padding: 0; box-sizing: border-box; }

  body {
    background: var(--bg);
    color: var(--text);
    font-family: var(--font-body);
    font-size: 18px;
    line-height: 1.7;
    overflow: hidden;
    height: 100vh;
    width: 100vw;
  }

  .deck { height: 100vh; width: 100vw; position: relative; }

  .slide {
    position: absolute; top: 0; left: 0; right: 0; bottom: 0;
    display: none;
    padding: 60px 80px;
    overflow-y: auto;
  }
  .slide.is-active { display: flex; flex-direction: column; justify-content: center; }

  /* Title slide */
  .slide-title { text-align: center; align-items: center; }
  .slide-title h1 {
    font-family: var(--font-display);
    font-size: 3.5rem; font-weight: 900;
    color: var(--gold);
    letter-spacing: -0.02em;
    margin-bottom: 16px;
  }
  .slide-title .subtitle {
    font-size: 1.4rem; color: var(--text-dim); font-weight: 300;
    margin-bottom: 8px;
  }
  .slide-title .meta {
    font-size: 1rem; color: var(--text-muted); margin-top: 24px;
  }

  /* General slide */
  h2 {
    font-family: var(--font-display);
    font-size: 2.2rem; font-weight: 700;
    color: var(--gold);
    margin-bottom: 32px;
    padding-bottom: 12px;
    border-bottom: 2px solid var(--gold-dim);
  }
  h3 { font-size: 1.3rem; font-weight: 600; color: var(--accent); margin: 20px 0 10px; }

  /* Cards */
  .card-grid { display: grid; gap: 16px; }
  .card-grid.cols-2 { grid-template-columns: 1fr 1fr; }
  .card-grid.cols-3 { grid-template-columns: 1fr 1fr 1fr; }
  .card-grid.cols-4 { grid-template-columns: 1fr 1fr 1fr 1fr; }

  .card {
    background: var(--bg-card);
    border: 1px solid var(--border);
    border-radius: var(--radius);
    padding: 20px 24px;
  }
  .card:hover { border-color: var(--gold-dim); box-shadow: var(--shadow); }
  .card h4 { font-size: 1rem; font-weight: 600; color: var(--gold); margin-bottom: 6px; }
  .card p { font-size: 0.9rem; color: var(--text-dim); line-height: 1.5; margin: 0; }
  .card code, .card .formula {
    font-family: var(--font-mono); font-size: 0.85rem;
    color: var(--accent2); background: rgba(63,185,80,0.1);
    padding: 2px 6px; border-radius: 4px;
  }

  /* Triple ring diagram */
  .triple-ring {
    display: flex; justify-content: center; align-items: center;
    gap: 0; width: 100%; min-height: 380px;
  }
  .ring {
    border-radius: 50%; display: flex; flex-direction: column;
    justify-content: center; align-items: center; text-align: center;
    padding: 20px;
  }
  .ring-outer {
    width: 600px; height: 600px;
    background: rgba(230,184,0,0.06); border: 3px solid rgba(230,184,0,0.3);
  }
  .ring-mid {
    width: 440px; height: 440px;
    background: rgba(88,166,255,0.06); border: 3px solid rgba(88,166,255,0.3);
  }
  .ring-inner {
    width: 300px; height: 300px;
    background: rgba(63,185,80,0.06); border: 3px solid rgba(63,185,80,0.3);
  }
  .ring h4 { color: var(--gold); font-size: 1.1rem; margin-bottom: 8px; }
  .ring p { color: var(--text-dim); font-size: 0.85rem; line-height: 1.5; }

  /* Table */
  table {
    width: 100%; border-collapse: collapse; font-size: 0.85rem;
  }
  th {
    text-align: left; padding: 8px 12px;
    color: var(--gold); border-bottom: 2px solid var(--gold-dim);
    font-weight: 600; white-space: nowrap;
  }
  td {
    padding: 7px 12px; border-bottom: 1px solid var(--border);
    color: var(--text-dim); vertical-align: top;
  }
  tr:hover td { background: var(--bg-elevated); }
  td:first-child { color: var(--accent); font-weight: 600; white-space: nowrap; }

  /* Genius list */
  .genius-list { columns: 2; column-gap: 40px; }
  .genius-list .item {
    break-inside: avoid; margin-bottom: 12px;
    padding: 10px 14px; background: var(--bg-card);
    border-radius: 8px; border-left: 3px solid var(--gold-dim);
    font-size: 0.88rem; line-height: 1.5;
  }
  .genius-list .item strong { color: var(--gold); }

  /* Flow diagram */
  .flow {
    display: flex; flex-wrap: wrap; align-items: center; gap: 12px;
    font-family: var(--font-mono); font-size: 0.82rem;
    justify-content: center; padding: 20px 0;
  }
  .flow .node {
    background: var(--bg-elevated); padding: 8px 14px;
    border-radius: 8px; border: 1px solid var(--border);
    white-space: nowrap;
  }
  .flow .arrow { color: var(--gold); font-size: 1.2rem; }
  .flow .stage { color: var(--accent); }
  .flow .cache { color: var(--accent2); }

  /* Layer stack */
  .layer-stack { display: flex; flex-direction: column; gap: 4px; }
  .layer {
    display: flex; align-items: center; gap: 16px;
    padding: 6px 16px; border-radius: 6px;
    font-size: 0.85rem;
  }
  .layer .num {
    width: 32px; height: 32px; border-radius: 50%;
    display: flex; align-items: center; justify-content: center;
    font-weight: 700; font-size: 0.85rem;
    flex-shrink: 0;
  }
  .layer .label { color: var(--text); font-weight: 500; flex: 1; }
  .layer .detail { color: var(--text-muted); font-size: 0.78rem; }
  .layer-app .num { background: rgba(230,184,0,0.2); color: var(--gold); }
  .layer-os .num { background: rgba(88,166,255,0.2); color: var(--accent); }
  .layer-hw .num { background: rgba(63,185,80,0.2); color: var(--accent2); }

  /* Hub-spoke */
  .hub-spoke {
    display: flex; align-items: center; justify-content: center;
    gap: 60px; min-height: 400px;
  }
  .hub {
    width: 160px; height: 160px; border-radius: 50%;
    background: linear-gradient(135deg, rgba(230,184,0,0.2), rgba(230,184,0,0.05));
    border: 3px solid var(--gold);
    display: flex; align-items: center; justify-content: center;
    text-align: center; font-weight: 700; font-size: 1.2rem;
    color: var(--gold);
  }
  .spokes-left, .spokes-right {
    display: flex; flex-direction: column; gap: 20px;
  }
  .spoke {
    padding: 10px 18px; background: var(--bg-card);
    border-radius: 8px; border: 1px solid var(--border);
    font-size: 0.9rem; text-align: center;
  }
  .spoke.math { border-left: 3px solid var(--accent); }
  .spoke.cs { border-left: 3px solid var(--accent2); }

  /* Blind spots */
  .blind-list { columns: 2; column-gap: 40px; }
  .blind-list .bs {
    break-inside: avoid; margin-bottom: 14px;
    padding: 12px 16px; background: var(--bg-elevated);
    border-radius: 8px; border: 1px solid var(--border);
  }
  .blind-list .bs h4 { font-size: 0.95rem; color: var(--accent); margin-bottom: 4px; }
  .blind-list .bs p { font-size: 0.82rem; color: var(--text-dim); line-height: 1.5; margin: 0; }

  /* Navbar */
  .nav {
    position: fixed; bottom: 20px; right: 20px;
    display: flex; gap: 8px; z-index: 100;
  }
  .nav button {
    background: var(--bg-elevated); color: var(--text);
    border: 1px solid var(--border); border-radius: 8px;
    padding: 8px 16px; cursor: pointer; font-size: 0.9rem;
    font-family: var(--font-body);
  }
  .nav button:hover { border-color: var(--gold); color: var(--gold); }
  .page-num {
    position: fixed; bottom: 24px; left: 24px;
    color: var(--text-muted); font-size: 0.9rem; z-index: 100;
  }

  /* Responsive */
  @media (max-width: 1024px) {
    .slide { padding: 30px 24px; }
    .card-grid.cols-3, .card-grid.cols-4 { grid-template-columns: 1fr 1fr; }
    .genius-list, .blind-list { columns: 1; }
    h1 { font-size: 2.5rem !important; }
    h2 { font-size: 1.6rem !important; }
  }
</style>
</head>
<body>

<main class="deck">

  <!-- Slide 1: Title -->
  <div class="slide slide-title is-active">
    <h1>CSAPP: A Programmer's<br>Perspective</h1>
    <div class="subtitle">系统知识图谱 · System Knowledge Map</div>
    <div class="meta">Randal E. Bryant &amp; David R. O'Hallaron · 第三版<br>方舟计划 · 课程总结</div>
  </div>

  <!-- Slide 2: Triple Ring -->
  <div class="slide">
    <h2>全书结构：三层同心圆</h2>
    <div class="triple-ring">
      <div class="ring ring-outer">
        <h4>Part I: Program Structure &amp; Execution</h4>
        <p>Ch1 漫游 → Ch2 数据表示 → Ch3 机器码<br>→ Ch4 处理器架构 → Ch5 性能优化 → Ch6 存储层次</p>
        <div style="margin-top:16px">
          <div class="ring ring-mid">
            <h4>Part II: Running Programs</h4>
            <p>Ch7 链接 → Ch8 异常控制流 → Ch9 虚拟内存</p>
            <div style="margin-top:12px">
              <div class="ring ring-inner">
                <h4>Part III: Interaction</h4>
                <p>Ch10 系统I/O<br>→ Ch11 网络编程<br>→ Ch12 并发编程</p>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>

  <!-- Slide 3: Chapter Summary Table -->
  <div class="slide">
    <h2>12章知识网络</h2>
    <table>
      <tr><th>Ch</th><th>主题</th><th>核心概念</th><th>关键公式 / 洞见</th></tr>
      <tr><td>1</td><td>计算机系统漫游</td><td>信息=位+上下文，三大抽象</td><td class="formula">S = 1/((1−α) + α/k)</td></tr>
      <tr><td>2</td><td>信息表示与处理</td><td>补码 / IEEE 754 / 字节序</td><td class="formula">V = (−1)^s × M × 2^E</td></tr>
      <tr><td>3</td><td>机器级表示</td><td>x86-64 指令集 / 栈帧</td><td>call / ret + %rsp ⇄ 栈</td></tr>
      <tr><td>4</td><td>处理器体系结构</td><td>ISA 抽象 / 流水线 / 冒险</td><td>吞吐率 = 1 / max(t<sub>stage</sub>)</td></tr>
      <tr><td>5</td><td>优化程序性能</td><td>优化金字塔 / 数据流图</td><td>关键路径 = 延迟界限</td></tr>
      <tr><td>6</td><td>存储器层次结构</td><td>局部性 / 缓存 / Memory Mountain</td><td>同一逻辑, 步长差异 → 20−40×</td></tr>
      <tr><td>7</td><td>链接</td><td>符号解析 / 重定位 / 动态链接</td><td>PIC + GOT + PLT 三位一体</td></tr>
      <tr><td>8</td><td>异常控制流</td><td>异常 / 进程 / 信号</td><td>4类异常: 中断·陷阱·故障·终止</td></tr>
      <tr><td>9</td><td>虚拟内存</td><td>页表 / TLB / malloc</td><td>一石三鸟: 缓存+管理+保护</td></tr>
      <tr><td>10</td><td>系统级 I/O</td><td>Unix I/O / 文件描述符</td><td>一切皆文件: fd 统一模型</td></tr>
      <tr><td>11</td><td>网络编程</td><td>socket / HTTP / TINY Server</td><td>socket = fd: Unix哲学的延伸</td></tr>
      <tr><td>12</td><td>并发编程</td><td>进程/线程/信号量/死锁</td><td>P/V 操作: 互斥+调度统一</td></tr>
    </table>
  </div>

  <!-- Slide 4: 18 Genius Design Points -->
  <div class="slide">
    <h2>18 个天才设计点</h2>
    <div class="genius-list">
      <div class="item"><strong>1. ISA</strong> — 顺序执行的"谎言"，软硬件之间最成功的抽象层</div>
      <div class="item"><strong>2. 虚拟内存</strong> — 一个间接层同时解决缓存 + 管理 + 保护</div>
      <div class="item"><strong>3. fork+execve</strong> — 分离设计让 shell 管道只用三行代码</div>
      <div class="item"><strong>4. 信号量 P/V</strong> — 两个原子操作统一互斥 + 调度的最小完备原语</div>
      <div class="item"><strong>5. Memory Mountain</strong> — 一张图解释整个存储层次，封面级震撼</div>
      <div class="item"><strong>6. Amdahl 定律</strong> — 串行部分是并行化不可逾越的天花板</div>
      <div class="item"><strong>7. PIC+GOT+PLT</strong> — 一个代码副本服务 N 个进程的极致内存效率</div>
      <div class="item"><strong>8. 异常 2×2 分类</strong> — 同步/异步 × 返回行为，4 格覆盖全部 ECF</div>
      <div class="item"><strong>9. COW 写时复制</strong> — 懒惰求值：fork 后不复制，写入时才复制</div>
      <div class="item"><strong>10. 循环嵌套顺序</strong> — 改变两行代码，矩阵乘法快 10×</div>
      <div class="item"><strong>11. 缓存冲突修复</strong> — 中间位索引 + B 字节 padding 消除 thrashing</div>
      <div class="item"><strong>12. Round-to-Even</strong> — IEEE 754 的反直觉舍入，消除统计偏倚</div>
      <div class="item"><strong>13. 缓存无处不在</strong> — 从 CPU 到浏览器，12 层缓存同一原理</div>
      <div class="item"><strong>14. 数据流图+关键路径</strong> — 性能从经验→可计算问题</div>
      <div class="item"><strong>15. Stack Canary</strong> — 矿工金丝雀→栈保护，最小代价最大收益</div>
      <div class="item"><strong>16. 预线程化</strong> — 主仆+对等+生产者-消费者的完美合题</div>
      <div class="item"><strong>17. 信号不排队</strong> — 约束即特性：位向量迫使鲁棒编程模式</div>
