## Lab 6: Shell Lab（Unix Shell 实现）

**来源**：CSAPP 3e Ch8。实现一个简单的 Unix shell，支持作业控制（job control）、前台/后台执行、信号处理（SIGINT/SIGTSTP/SIGCHLD）。

---

### 核心数据结构

```c
#define MAXLINE 1024
#define MAXARGS 128
#define MAXJOBS 16

typedef enum { FG, BG, ST } job_state;

struct job_t {
    pid_t pid;
    int jid;            // 作业 ID（1,2,3...）
    job_state state;     // FG, BG, ST (stopped)
    char cmdline[MAXLINE];
};
struct job_t jobs[MAXJOBS];

volatile sig_atomic_t pid;  // 信号处理器和主程序共享
```

---

### 主循环

```c
void eval(char *cmdline) {
    char *argv[MAXARGS];
    int bg;
    sigset_t mask;

    bg = parseline(cmdline, argv);  // 解析命令行，返回是否后台

    if (!builtin_cmd(argv)) {
        sigemptyset(&mask);
        sigaddset(&mask, SIGCHLD);
        sigprocmask(SIG_BLOCK, &mask, NULL);  // 阻塞 SIGCHLD

        if ((pid = fork()) == 0) {
            // 子进程
            sigprocmask(SIG_UNBLOCK, &mask, NULL);
            setpgid(0, 0);  // 新进程组
            if (execve(argv[0], argv, environ) < 0) {
                printf("%s: Command not found\n", argv[0]);
                exit(0);
            }
        }

        // 父进程
        addjob(jobs, pid, (bg ? BG : FG), cmdline);
        sigprocmask(SIG_UNBLOCK, &mask, NULL);

        if (!bg) {
            waitfg(pid);  // 前台作业：等待完成
        } else {
            printf("[%d] (%d) %s", pid2jid(pid), pid, cmdline);
        }
    }
}
```

**关键设计**：fork 前阻塞 SIGCHLD——防止子进程在 `addjob` 之前退出导致信号处理器找不到作业。fork 后子进程解除阻塞并设置独立进程组。

---

### 信号处理器

```c
// SIGCHLD: 回收已终止或停止的子进程
void sigchld_handler(int sig) {
    int old_errno = errno;
    pid_t pid;
    int status;

    while ((pid = waitpid(-1, &status, WNOHANG | WUNTRACED)) > 0) {
        if (WIFEXITED(status)) {
            deletejob(jobs, pid);  // 正常退出
        } else if (WIFSIGNALED(status)) {
            printf("Job [%d] (%d) terminated by signal %d\n",
                   pid2jid(pid), pid, WTERMSIG(status));
            deletejob(jobs, pid);
        } else if (WIFSTOPPED(status)) {
            printf("Job [%d] (%d) stopped by signal %d\n",
                   pid2jid(pid), pid, WSTOPSIG(status));
            getjobpid(jobs, pid)->state = ST;
        }
    }
    errno = old_errno;
}

// SIGINT (Ctrl-C): 终止前台作业
void sigint_handler(int sig) {
    pid_t fgpid = fgpid(jobs);
    if (fgpid) kill(-fgpid, SIGINT);  // 负 pid → 进程组
}

// SIGTSTP (Ctrl-Z): 停止前台作业
void sigtstp_handler(int sig) {
    pid_t fgpid = fgpid(jobs);
    if (fgpid) kill(-fgpid, SIGTSTP);
}
```

**三个关键细节**：
1. `waitpid` 的 `WUNTRACED` 标志——让 waitpid 也捕获停止的（而不仅是终止的）子进程
2. `while (waitpid > 0)` 而非 `if`——因为 pending 信号是位向量，多个 SIGCHLD 只触发一次
3. `kill(-pid, sig)` 的负号——向整个进程组发送信号（shell 需要控制子进程及其子进程）

---

### 内置命令

```c
int builtin_cmd(char **argv) {
    if (!strcmp(argv[0], "quit")) exit(0);
    if (!strcmp(argv[0], "jobs")) { listjobs(jobs); return 1; }
    if (!strcmp(argv[0], "bg"))   { do_bgfg(argv, BG); return 1; }
    if (!strcmp(argv[0], "fg"))   { do_bgfg(argv, FG); return 1; }
    return 0;  // 不是内置命令
}

void do_bgfg(char **argv, int bg) {
    struct job_t *job = getjobpid(jobs, atoi(argv[1]));
    kill(-job->pid, SIGCONT);          // 发送 SIGCONT 恢复
    job->state = (bg ? BG : FG);
    if (!bg) waitfg(job->pid);         // 前台：等待完成
}
```

**做 Shell Lab 的收获**：实现 Shell 让你同时面对进程创建（fork/execve）、信号处理（SIGCHLD/SIGINT/SIGTSTP）、并发竞态（fork 前阻塞信号、信号处理器的 while 循环、waitpid 的 WNOHANG/WUNTRACED）。Shell 是一个**并发系统**——父进程和子进程、前台和后台作业、多个信号之间都在竞争。写对 Shell 意味着你真正理解了 CSAPP Ch8。

