## Lab 8: Proxy Lab（并发 Web 代理）

**来源**：CSAPP 3e Ch11-12。三个部分：顺序代理 → 并发代理（多线程）→ 带缓存的并发代理。

---

### Part A：顺序 Web 代理

**功能**：接受浏览器 HTTP 请求 → 转发到目标服务器 → 读取响应 → 返回浏览器。

```c
int main(int argc, char **argv) {
    int listenfd, connfd;
    char hostname[MAXLINE], port[MAXLINE];
    socklen_t clientlen;
    struct sockaddr_storage clientaddr;

    listenfd = Open_listenfd(argv[1]);  // 监听端口

    while (1) {
        clientlen = sizeof(clientaddr);
        connfd = Accept(listenfd, (SA *)&clientaddr, &clientlen);
        Getnameinfo((SA *)&clientaddr, clientlen, 
                     hostname, MAXLINE, port, MAXLINE, 0);
        printf("Accepted connection from %s:%s\n", hostname, port);
        doit(connfd);    // 处理一个事务
        Close(connfd);
    }
}
```

---

### doit：处理 HTTP 事务

```c
void doit(int fd) {
    char buf[MAXLINE], method[MAXLINE], uri[MAXLINE], version[MAXLINE];
    char hostname[MAXLINE], path[MAXLINE], port[MAXLINE];
    rio_t rio;
    int clientfd;

    Rio_readinitb(&rio, fd);
    Rio_readlineb(&rio, buf, MAXLINE);
    sscanf(buf, "%s %s %s", method, uri, version);

    // 只处理 GET
    if (strcasecmp(method, "GET")) {
        clienterror(fd, method, "501", "Not Implemented", "...");
        return;
    }

    // 解析 URI: http://hostname:port/path
    parse_uri(uri, hostname, port, path);

    // 转发请求到目标服务器
    clientfd = Open_clientfd(hostname, port);

    // 构造转发请求（去掉 http://hostname 前缀）
    sprintf(buf, "GET %s %s\r\n", path, version);
    Rio_writen(clientfd, buf, strlen(buf));

    // 转发客户端请求头
    while (strcmp(buf, "\r\n")) {
        Rio_readlineb(&rio, buf, MAXLINE);
        // 过滤掉 Host/Connection/Proxy-Connection/User-Agent 头（自己构造）
        if (!strncasecmp(buf, "Host:", 5) ||
            !strncasecmp(buf, "Connection:", 11) ||
            !strncasecmp(buf, "Proxy-Connection:", 17) ||
            !strncasecmp(buf, "User-Agent:", 11))
            continue;
        Rio_writen(clientfd, buf, strlen(buf));
    }

    // 读取服务器响应并转发给客户端
    Rio_readinitb(&rio, clientfd);
    size_t n;
    while ((n = Rio_readlineb(&rio, buf, MAXLINE)) != 0)
        Rio_writen(fd, buf, n);

    Close(clientfd);
}
```

---

### Part B：多线程并发代理

**改动**：主线程 accept → 将 connfd 传递给工作线程 → 工作线程调用 doit。

```c
// 预线程化模型
#define NTHREADS 4
#define SBUFSIZE 16

sbuf_t sbuf;  // 共享的有界缓冲区

void *thread(void *vargp) {
    Pthread_detach(pthread_self());
    while (1) {
        int connfd = sbuf_remove(&sbuf);  // 从缓冲区取连接
        doit(connfd);
        Close(connfd);
    }
}

int main(int argc, char **argv) {
    int listenfd = Open_listenfd(argv[1]);
    sbuf_init(&sbuf, SBUFSIZE);

    // 创建工作线程池
    pthread_t tid;
    for (int i = 0; i < NTHREADS; i++)
        Pthread_create(&tid, NULL, thread, NULL);

    while (1) {
        connfd = Accept(listenfd, ...);
        sbuf_insert(&sbuf, connfd);  // 放入缓冲区
    }
}
```

---

### 有界缓冲区（sbuf — 生产者-消费者）

```c
typedef struct {
    int *buf;          // 缓冲区数组
    int n;             // 最大槽位数
    int front, rear;   // 队首、队尾
    sem_t mutex;       // 互斥锁
    sem_t slots;       // 空槽信号量（生产者等待）
    sem_t items;       // 满槽信号量（消费者等待）
} sbuf_t;

void sbuf_insert(sbuf_t *sp, int item) {
    sem_wait(&sp->slots);    // ① 先申请空槽（调度）
    sem_wait(&sp->mutex);    // ② 再获取互斥锁
    sp->buf[(++sp->rear) % sp->n] = item;
    sem_post(&sp->mutex);
    sem_post(&sp->items);    // ③ 通知有新内容
}
```

**关键细节**：P 操作的顺序必须是 slots/mutex 而不能是 mutex/slots——否则缓冲区满时生产者持有 mutex 但阻塞在 slots → 消费者拿不到 mutex 来消费 → 死锁。这是 CSAPP Ch12 中「调度先于互斥」规则的直接体现。

---

### Part C：带缓存的代理

**改动**：在 doit 中加入缓存查找。如果请求的 URL 在缓存中 → 直接返回。否则 → 转发请求 → 将响应存入缓存 → 返回。

```c
// 缓存结构（简单的 reader-writer 锁）
typedef struct {
    char uri[MAXLINE];
    char *content;
    size_t content_size;
    struct cache_block *next;
    int lru_counter;
    sem_t rwlock;  // 1 = 可用, 0 = 写入中
} cache_block;

cache_block *cache_head;
sem_t cache_mutex;

// 读缓存（多个读者可同时读）
cache_block *find_cache(char *uri) {
    sem_wait(&cache_mutex);        // 保护链表遍历
    for (cache_block *b = cache_head; b; b = b->next) {
        if (!strcmp(b->uri, uri)) {
            b->lru_counter = 0;    // LRU 更新
            sem_post(&cache_mutex);
            return b;              // 读锁不阻塞
        }
    }
    sem_post(&cache_mutex);
    return NULL;
}

// 写缓存（独占访问）
void insert_cache(char *uri, char *content, size_t size) {
    evict_if_needed();  // 如果缓存满，驱逐 LRU 块

    sem_wait(&cache_mutex);
    cache_block *newb = malloc(sizeof(cache_block));
    strcpy(newb->uri, uri);
    newb->content = malloc(size);
    memcpy(newb->content, content, size);
    newb->content_size = size;
    newb->next = cache_head;
    cache_head = newb;
    sem_post(&cache_mutex);
}
```

---

### doit 中的缓存集成

```c
void doit(int fd) {
    // ... 解析 URI ...

    // 检查缓存
    cache_block *cached = find_cache(uri);
    if (cached) {
        Rio_writen(fd, cached->content, cached->content_size);
        return;
    }

    // 未命中 → 转发请求
    clientfd = Open_clientfd(hostname, port);
    // ... 发送请求 ...

    // 读取完整响应到缓冲区
    char response[MAX_OBJECT_SIZE];
    size_t resp_size = 0;
    Rio_readinitb(&rio, clientfd);
    while ((n = Rio_readlineb(&rio, buf, MAXLINE)) != 0) {
        memcpy(response + resp_size, buf, n);
        resp_size += n;
    }

    // 存入缓存 + 返回客户端
    insert_cache(uri, response, resp_size);
    Rio_writen(fd, response, resp_size);
    Close(clientfd);
}
```

**做 Proxy Lab 的收获**：这个 Lab 是 CSAPP 全书的最终合题。一个代理服务器用到了：socket 编程（Ch11）、I/O（Ch10）、进程和信号（Ch8，虽然这里用线程但概念相通）、并发同步（Ch12 的有界缓冲区 + 信号量 + 读者-写者）、缓存（Ch6 的替换策略直接应用于 HTTP 缓存）、内存管理（Ch9 的 malloc 用于缓存块分配）。CSAPP 的三大部分在此 Lab 中汇聚——你写的每一行代码都在引用前面学到的概念。

